#!/usr/bin/env bash
# FREE. No password, no gas. Simulates creating the three gated mandates.
# Each cast call should RETURN the mandateId. If any reverts, the params are
# wrong (BadConfig / Unbounded) and nothing has been spent finding out.
set -u
RPC=https://rpc.testnet.arc.io
MM=0x3744E93B9e796E05CB66311d897559B6F3860196
PAYER=0xB56A7008dcDa0B7c603a2E1fA15fef58cff0Dcc0







echo "=== salt 3, identity gate (agentId 16330, no owner pin), flags 25 ==="
echo "  predicted 0xd97ac489ddcff3d515cbdf5b5a04d283f09c78b6bfd4c0e0211e82372ad4af61"
echo -n "  returned  " ; cast call $MM $CD3 --from $PAYER --rpc-url $RPC

echo "=== salt 4, credential gate minResponse=100, no staleness, flags 41 ==="
echo "  predicted 0x196db6b1679927aa20e05db057939393741f22e8ea93a748c2706ea78b11312a"
echo -n "  returned  " ; cast call $MM $CD4 --from $PAYER --rpc-url $RPC

echo "=== salt 5, credential gate minResponse=1, maxStaleness=86400, flags 41 ==="
echo "  predicted 0xf1836df74ff8dfc0f79180085b2fbf7442cf8a860ae7bc07a04347aa69063986"
echo -n "  returned  " ; cast call $MM $CD5 --from $PAYER --rpc-url $RPC

echo "=== gas estimates, so we know what the three sends will cost ==="
for cd in $CD3 $CD4 $CD5; do
  cast estimate $MM $cd --from $PAYER --rpc-url $RPC
done
